#!/usr/bin/env python3
"""Minimal ANSI renderer + driver for walk experiments."""
import json, subprocess, sys, re

def run(expr=None, keys=(), rows=24, cols=80, cwd="/tmp/A7_sb", args=None, extra_env=None):
    env = {}
    if expr is not None:
        env["WALK_STATUS_BAR"] = expr
    if extra_env:
        env.update(extra_env)
    spec = {"exe": "/workspace/executable", "args": args or [],
            "cwd": cwd, "rows": rows, "cols": cols, "env": env,
            "keys": [[d, k] for d, k in keys]}
    p = subprocess.run(["python3", "/tmp/drive.py", json.dumps(spec)],
                       capture_output=True, cwd="/tmp",
                       env={"PATH": "/usr/bin:/bin", "WALK_X": "1"})
    return p.stdout

class Screen:
    def __init__(self, rows, cols):
        self.rows, self.cols = rows, cols
        self.grid = [[" "] * cols for _ in range(rows)]
        self.r = self.c = 0
    def put(self, ch):
        if self.r < self.rows and self.c < self.cols:
            self.grid[self.r][self.c] = ch
        self.c += 1
    def text(self):
        return "\n".join("".join(row) for row in self.grid)

def render(data, rows=24, cols=80):
    s = Screen(rows, cols)
    i = 0
    text = data.decode("utf-8", "replace")
    while i < len(text):
        ch = text[i]
        if ch == "\x1b":
            m = re.match(r"\x1b\[([0-9;?]*)([A-Za-z@`])", text[i:])
            if m:
                params, cmd = m.group(1), m.group(2)
                i += m.end()
                if cmd in "Hf":
                    parts = params.split(";") if params else []
                    s.r = (int(parts[0]) - 1) if len(parts) > 0 and parts[0] else 0
                    s.c = (int(parts[1]) - 1) if len(parts) > 1 and parts[1] else 0
                elif cmd == "A": s.r = max(0, s.r - (int(params) if params else 1))
                elif cmd == "B": s.r = min(rows - 1, s.r + (int(params) if params else 1))
                elif cmd == "C": s.c = min(cols - 1, s.c + (int(params) if params else 1))
                elif cmd == "D": s.c = max(0, s.c - (int(params) if params else 1))
                elif cmd == "G": s.c = (int(params) - 1) if params else 0
                elif cmd == "d": s.r = (int(params) - 1) if params else 0
                elif cmd == "J":
                    if params in ("2", "3"):
                        s.grid = [[" "] * cols for _ in range(rows)]
                elif cmd == "K":
                    mode = params or "0"
                    if mode == "0":
                        for x in range(s.c, cols): s.grid[s.r][x] = " "
                    elif mode == "2":
                        s.grid[s.r] = [" "] * cols
                continue
            m = re.match(r"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)", text[i:])
            if m:
                i += m.end(); continue
            m = re.match(r"\x1b[()][A-Za-z0-9]", text[i:])
            if m:
                i += m.end(); continue
            m = re.match(r"\x1b[>=<]", text[i:])
            if m:
                i += m.end(); continue
            i += 1
            continue
        if ch == "\r": s.c = 0
        elif ch == "\n": s.r = min(rows - 1, s.r + 1)
        elif ch == "\x08": s.c = max(0, s.c - 1)
        elif ch == "\x07": pass
        elif ch >= " ":
            s.put(ch)
        i += 1
    return s.text()

if __name__ == "__main__":
    expr = sys.argv[1]
    keys = [tuple(k) for k in json.loads(sys.argv[2])] if len(sys.argv) > 2 else []
    rows, cols = 24, 80
    if len(sys.argv) > 3:
        rows, cols = map(int, sys.argv[3].split(","))
    data = run(expr, keys, rows, cols)
    print("=== RENDER ===")
    print(render(data, rows, cols))
    print("=== REPR (last 3000) ===")
    print(repr(data[-3000:]))

#!/usr/bin/env python3
"""Batch-run status bar expressions, print rendered status line (row 11 for /tmp/A7_sb)."""
import render, sys, json

def probe_exprs(exprs, row=11, rows=24, cols=80, cwd="/tmp/A7_sb", keys=None):
    for expr in exprs:
        k = list(keys) if keys else []
        k.append((0.2, "q"))
        data = render.run(expr, k, rows, cols, cwd=cwd)
        scr = render.render(data, rows, cols).split("\n")
        line = scr[row].rstrip() if len(scr) > row else "<NO ROW>"
        print(f"EXPR {expr!r}\n  -> {line!r}")

if __name__ == "__main__":
    probe_exprs(json.loads(sys.argv[1]))
